    "answer": 0,
    "explanation": "まず正しい知識を確認する。ICCは、集団殺害犯罪・人道に対する犯罪・戦争犯罪・侵略犯罪という重大な犯罪について、国家ではなく個人の刑事責任を国際法に基づいて追及する常設の裁判所である。一方、国際司法裁判所（ICJ）は国家間の紛争を扱う機関であり、個人に有罪判決を下すことはない。したがって、ICJの有罪判決からICCへ上訴するという選択肢3・4は前提となる知識自体が誤り。残る1と2のうち、こうした手続を設ける目的（推察）として妥当なのは、処罰の可能性を示すことで重大犯罪の発生そのものを抑止・防止するという1である。2の「各国の刑事裁判における適法手続の保障」はICCの目的ではなく、各国の国内法が担うものである。",
