    "answer": 5,
    "explanation": "三人の思想家が自然状態をどうとらえたかで見分ける。\nア＝ロック（c）。『統治二論』。ロックは自然状態にも理性という自然法があり、人は生命・自由・財産（所有物）を侵してはならないと考えた。「自然法」「所有物」という語が手がかりになる。ロックのこの考えは、政府が権利を侵したときの抵抗権につながり、アメリカ独立宣言などに影響を与えた。\nイ＝ホッブズ（b）。『リヴァイアサン』。ホッブズは、共通の権力がなければ人間は「万人の万人に対する闘争」の状態に置かれ、何の保証もなく生きることになると論じた。「共通の権力なしに」という表現がホッブズの特徴である。\nウ＝グロティウス（a）。『戦争と平和の法』。戦争のさなかでも国家間には自然法と諸国民の合意に基づく法（共通法）があると説き、「国際法の父」と呼ばれる。「戦争」「万民の合意」が手がかり。\nよってア－c、イ－b、ウ－a。国際社会は各国の上に立つ世界政府がない点でホッブズのいう自然状態に似ているが、グロティウス以来の国際法によって一定の秩序が保たれている、という文脈の問題である。",
