    "noShuffle": true,
    "question": "二院制をとる国の議会のあり方について、今日の日本、アメリカ、イギリスの議会に関する次の記述a～cのうち、正しいものはどれか。当てはまるものをすべて選び、その組合せとして最も適当なものを、後のうちから一つ選べ。\n\na　日本では、両議院は全国民を代表する選挙された議員で組織するものとされており、衆議院と参議院の議員ともに国民の直接選挙によって選出されている。衆議院で可決し参議院でこれと異なった議決をした法律案は、衆議院で出席議員の3分の2以上の多数で再び可決したときは、法律となる。\nb　アメリカでは、連邦議会の上院議員は各州から2名ずつ選出されるのに対し、下院議員は各州から人口に比例して選出されている。連邦議会は立法権や予算の議決権などをもつが、政府高官人事への同意など下院にのみ与えられている権限もある。\nc　イギリスでは、上院は非公選の貴族を中心に組織されるのに対し、下院は国民の直接選挙によって選出される議員によって組織される。下院優越の原則が確立しており、下院が国政の中心に位置している。下院には解散もあるが、解散できる条件は限られている。",
