    "explanation": "部分的核実験禁止条約（PTBT、1963年）は、大気圏内・宇宙空間・水中での核実験を禁止したが、地下核実験は禁止していない。地下核実験を含むあらゆる核実験を禁止しようとしたのが包括的核実験禁止条約（CTBT、1996年採択）である。したがって選択肢1が誤り。\n他は正しい。CTBTは、アメリカ・中国などの発効要件国が批准していないため未発効である。核拡散防止条約（NPT、1968年採択・1970年発効）は、1967年1月1日以前に核実験を行ったアメリカ・ロシア（旧ソ連）・イギリス・フランス・中国の5か国のみを核兵器国と認め、それ以外の国への拡散を防ごうとするものである。第一次戦略兵器削減条約（START I、1991年署名）は、米ソ間で戦略核弾頭の削減を初めて定めた。",
