    "stem": "資料\n表現の自由の意義として、さらに、各人が自己の意見を自由に表明し、競争することによって、真理に到達することができるという、「思想の自由市場論」があげられている…（略）…。「思想の自由市場論」は、アメリカの連邦最高裁判所のホームズ裁判官が、「真理の最良の判定基準は、市場における競争のなかで、みずからを容認させる力をもっているかどうかである」と述べたもので…（略）…ある。\n（出所）野中俊彦・中村睦男・高橋和之・高見勝利『憲法Ⅰ〔第5版〕』\n\nＸ：この資料は、真理に到達するための筋道について論じているみたいだね。でも、人々の意見は多様だし、思想に真理なんてあるのかな。\nＹ：ここでの真理は、唯一絶対の真理とは違うよね。人々の思想に唯一の真理なんて普通は存在しないからこそ、思想の自由市場を説いたのではないかな。\nＸ：そうだね。この資料の考え方を踏まえると、日本国憲法で定めている検閲の禁止は、　ア　ためにも大事なんだね。\nＹ：資料の考え方を、現実の問題に当てはめてみるとどうだろうね。たとえば、SNS（ソーシャル・ネットワーキング・サービス）上で、アルゴリズムによって自分の考えと同じ意見ばかり表示されるとしたら、どうかな。\nＸ：その場合、この資料にある思想の自由市場の前提である競争が　イ　されるんじゃないかな。ほかにも、現実の問題に当てはめて考えることができそうだね。\n\nアに当てはまる記述\nａ　危険な言論を取り除くことで、思想の自由市場を健全に保ち続ける\nｂ　意見の自由なやりとりを確保することで、真理を探究し続ける\n\nイに当てはまる語句\nｃ　促進\nｄ　阻害",
    "question": "会話文中の　ア　に当てはまる記述と　イ　に当てはまる語句の組合せとして最も適当なものを、次のうちから一つ選べ。",
