    "stem": "防災や減災を目的とした公共の取組みは、時として個人の権利と衝突する。たとえば、災害から個人の生命を守るために防潮堤や遊水地を設置する場合、設置する場所の土地所有者の意思に反してでも、公共の利益のために当該土地が強制的に収用されることがありうる。ただし、その場合には、憲法で定められた　ア　が適切になされる必要がある。\n防災や減災の担い手は国家だけではない。「自助、共助、公助」の観点からは、住民が自分で防災や減災に取り組むだけでなく、国や地方公共団体とともに、地域コミュニティや地元企業といった主体も災害対策に関与することが求められる。たとえば、国や地方公共団体が洪水浸水想定区域を指定することは、　イ　に該当する。さらに、そうした指定をもとに防災や減災について話し合う集会を設けるなど、日頃からリスクコミュニケーションを活発化することに、地域の住民などが関与することも必要となる。",
