    "question": "次の記述ア～ウは、多国間条約について述べたものであり、後の記述ａ～ｃは、それぞれの多国間条約の運用上の特徴を説明したものである。ア～ウとａ～ｃの組合せとして最も適当なものを、後のうちから一つ選べ。\n\nア　WTO協定の下では、意思決定方式の一つとしてネガティブ・コンセンサスが採用されている。\nイ　国際人権規約の下では、締約国に対して履行状況に関する報告を求め、審査を行う制度が導入されている。\nウ　国連気候変動枠組条約の下では、継続的に政府間交渉を行う場として締約国会議（COP）が設置されている。\n\nａ　まずは基本となる条約において国々の共通利益や目的を設定し、制度を構築する。その制度の下で協議を行いながら、実現の方法や国々の義務を新たに条約として定め具体化していくことをめざしている。\nｂ　専門家で構成される機関が、各国の行動を条約に照らして定期的に評価し、条約の規定を遵守しているかどうかを判断する。条約の内容がすべての締約国において適切に実現されることをめざしている。\nｃ　締約国間の紛争が付託された場合、全締約国が一致して反対しない限り、紛争解決手続が開始され、また紛争解決に関する判断も採択される。紛争解決機能を強化して、ルールに基づく安定的な秩序の形成をめざしている。",
