    "answer": 0,
    "explanation": "ア　都市機能を中心部に集約し、公共交通で結んで生活の利便と行政の効率を高めるまちづくりの考え方をコンパクトシティという。富山市や青森市などの取り組みが知られる。ミニマム・アクセスは、ウルグアイ・ラウンドの合意にもとづく最低輸入機会（日本ではコメの最低輸入量）のことで、まちづくりとは関係がない。\nイ　応援したい地方公共団体へ寄付をすると所得税・住民税が控除される仕組みは、2008年に始まったふるさと納税である。独自課税（法定外税）は地方公共団体が条例で独自に設ける税であり、寄付ではない。\nよって1が正しい。",
