    "id": "civics-h30-center-1-1",
    "sourceQuestion": "第1問 問1（解答番号1）",
    "domain": "政治",
    "field": "民主政治",
    "topic": "夜警国家観と立憲主義",
    "points": 2,
    "stemTitle": "リード文　国家の役割と租税負担",
    "stem": "近代国家は租税を課し、それを財源に人々の要望やニーズを充足する政策を実施している。課税権のような強い権力が国家に付与されているのは、領域内の秩序の維持など公共的なサービスを提供するためである。しかし、その権力が濫用されれば、個人の自由や権利が侵害されかねない。このような問題を避けるために、国家権力を制限するのが憲法である。たとえば、政治制度について権力分立が憲法で定められている。法の支配を実現し、人権の保護を確保する役割を果たすのが裁判所である。さらに、人々が国政の方向性とその内実をチェックするために、国政の監視に必要な権限が議会に与えられている。\n18、19世紀の国家は財産権の保護や治安の維持などを主に担っており、その支出は小規模であった。このように国家の役割を、国防、司法、治安の維持に限定する考え方は「　ア　」観という。しかし、国家の役割を消極的にとらえる考えは、その後批判されるようになった。なぜならば、人々の市場における自発的な取引だけでは、社会的に望ましい結果がもたらされるとは限らないからである。\nそのため、20世紀には、国家において政府の果たす役割が市場との関係で、かつてよりも重要性を高めた。たとえば、拡大する貧富の格差を是正するために、所得の再分配政策が多くの国で実施されている。また、電力など大規模な設備を必要とする分野では、独占が発生しやすいため、価格規制のような政府介入が必要になる場合もある。しかし、政府活動の非効率性が指摘され始め、その活動や裁量の範囲の妥当性が問われるようになった。\n今日の国際情勢の変化は、国家の役割のあり方を改めて問い直すものとなっている。たとえば、冷戦の終結やテロの頻発などを受けて、国家の安全保障をめぐるさまざまな問題に対処するためには、政府の権限拡大が必要になることもあるだろう。しかし、これまで見てきたように近代国家の歴史が示すのは、「　イ　」が欠かせないということである。",
    "question": "本文中の空欄ア・イに当てはまる語句の組合せとして最も適当なものを、次のうちから一つ選べ。",
    "choices": [
      "ア　福祉国家　　イ　国家の権力に対する憲法上の制約をなくす仕組み",
      "ア　福祉国家　　イ　人々に対する国家の介入を制約する仕組み",
      "ア　夜警国家　　イ　国家の権力に対する憲法上の制約をなくす仕組み",
      "ア　夜警国家　　イ　人々に対する国家の介入を制約する仕組み"
    ],
    "answer": 3,
    "explanation": "ア　18〜19世紀の国家像を問うている。国家の役割を国防・司法・治安の維持という最小限にとどめる考え方を、ドイツの社会主義者ラッサールが批判的に「夜警国家」と呼んだ。福祉国家は、社会権の保障のために国家が経済や社会保障へ積極的に関与する20世紀以降の国家像であり、「その支出は小規模であった」という文とかみ合わない。\nイ　直前で「政府の権限拡大が必要になることもある」と述べたうえで「しかし」と受けているので、権限の拡大を押しとどめる側の内容が入る。第1段落は、憲法によって国家権力を制限し、権力分立・裁判所・議会の監視で個人の自由と権利を守ることを述べていた。これが立憲主義であり、「人々に対する国家の介入を制約する仕組み」が当てはまる。\nよって4が正しい。",
    "choiceNotes": [
      "誤り。アもイも当てはまらない。福祉国家は国家の役割を広げる考え方であり、また「憲法上の制約をなくす」ことは、憲法で国家権力を縛るというリード文の趣旨と正反対である。",
      "誤り。イは正しいが、アが誤り。福祉国家は社会権の保障のために国家が積極的に介入する国家像で、役割を国防・司法・治安に限定する説明にはならない。",
      "誤り。アは正しいが、イが誤り。リード文は憲法によって国家権力を制限することの重要性を述べており、制約をなくす仕組みでは逆の意味になる。",
      "正解。アは国家の役割を国防・司法・治安の維持に限る夜警国家観、イは国家権力を憲法で縛る立憲主義の考え方である。"
    ],
