    "explanation": "ア　アメリカの大統領は法案提出権をもたない。立法を促すときは一般教書・予算教書・経済教書という教書を議会へ送るだけである。したがって「法案提出」では誤りで、「教書送付」が入る。\nイ　空欄イは、アメリカの議会が大統領に対してもたない権限と、イギリスの下院が内閣に対してもつ権限の両方に入る。議院内閣制の下で下院が内閣に対してもつのは内閣不信任決議権であり、大統領制のアメリカにはこれがない。「弾劾」を入れると、アメリカ議会が大統領を弾劾できるという事実と矛盾してしまう。\nウ　大統領制では行政府と立法府が別々に選ばれ、解散も不信任もない。したがって権力分立は議院内閣制より厳格である。\nよって3が正しい。",
