    "field": "平和主義",
    "topic": "防衛装備移転三原則と国家安全保障会議",
    "points": 3,
    "question": "日本の安全保障をめぐる法制度や政策についての記述として正しいものを、次のうちから一つ選べ。",
    "choices": [
      "2014年に政府が決定した防衛装備移転三原則によれば、武器や関連技術の輸出は全面的に禁止されている。",
      "自衛隊の最高指揮監督権は、防衛大臣が有している。",
      "2015年に成立した安全保障関連法によれば、日本と密接な関係にある他国に対する攻撃によって日本の存立が脅かされ、国民の権利が根底から覆される明白な危険がある場合でも、武力行使は禁止されている。",
      "安全保障に関する重要事項を審議する機関として、国家安全保障会議を内閣に設置している。"
    ],
    "answer": 3,
    "explanation": "4が正しい。国家安全保障会議（日本版NSC）は、2013年に従来の安全保障会議を改組して内閣に置かれた機関である。内閣総理大臣・内閣官房長官・外務大臣・防衛大臣による四大臣会合を中心に、外交・防衛の重要事項を機動的に審議する。事務局として内閣官房に国家安全保障局が置かれている。",
    "choiceNotes": [
      "誤り。防衛装備移転三原則は、1967年以来の武器輸出三原則に代えて2014年に決定されたもので、移転を禁じる場合を定めたうえで、平和貢献や日本の安全保障に資する場合には厳格な審査の下で移転を認める内容である。全面禁止ではない。",
      "誤り。自衛隊の最高指揮監督権は内閣総理大臣がもつ（自衛隊法7条）。防衛大臣は総理大臣の指揮監督を受けて隊務を統括する。軍事より文民の政治が優位するという文民統制（シビリアン・コントロール）の表れである。",
      "誤り。安全保障関連法は、この場合を「存立危機事態」と位置づけ、他に手段がないことなどを条件に集団的自衛権の限定的な行使を認めた。武力行使が一律に禁止されているわけではない。",
      "正解。国家安全保障会議は2013年に内閣へ設置され、外交・安全保障の重要事項を審議する。"
    ],
