    "stemTitle": "表　男女間の格差の国際比較",
    "stem": "男性の賃金を100とした場合の女性の賃金／管理職に占める女性の割合（％）／閣僚に占める女性の割合（％）／最高裁判所裁判官に占める女性の割合（％）の順に示す。\n日本……72／11／22／17\nアメリカ……83／44／26／25\nドイツ……81／29／33／21\nフランス……85／33／50／35\n（注）男性の賃金を100とした場合の女性の賃金と管理職に占める女性の割合とは2014年の数値である。閣僚に占める女性の割合は2015年の数値である。最高裁判所裁判官に占める女性の割合は、日本とアメリカが2013年の数値であり、ドイツとフランスが2012年の数値である。\n（資料）独立行政法人 労働政策研究・研修機構（編）『データブック国際労働比較（2016年版）』およびOECD, Government at a Glance 2013, 2015（OECD Webページ）により作成。",
    "question": "上の表は、男性の賃金を100とした場合の女性の賃金、管理職に占める女性の割合、閣僚に占める女性の割合、最高裁判所裁判官に占める女性の割合の国際比較を示したものである。この表から読みとれる内容として正しいものを、次のうちから一つ選べ。",
