    "answer": 0,
    "explanation": "ア　「協賛のための機関」「外見的立憲主義」が手がかりである。大日本帝国憲法の下で帝国議会は天皇の立法権に協賛する機関と位置づけられ、憲法は形の上では立憲主義をとりながら天皇に強い権限を残していた（外見的立憲主義）。現在の国会議事堂もこの時代に建てられたものなので、アは日本の衆議院（A）である。\nイ　与党と野党が向かいあって座り、床に踏み越えてはならない線（ソードライン）が引かれているのはイギリス下院の特徴である。剣で斬り合わず討論で決めるという議会政治の伝統を示すもので、イはイギリスの下院（B）である。\nウ　「人は自由で平等なものとして出生する」は1789年のフランス人権宣言の一節である。その頃の議会で議長席から見て左に急進派、右に保守派が座ったことが左翼・右翼の語源になったので、ウはフランスの下院（C）である。\nよって1が正しい。",
