    "question": "上の図は、日本の地方財政における市町村の歳出のうち、人件費、扶助費、普通建設事業費の推移を示したものである。人件費は職員給与などに充てられ、扶助費は生活保護や高齢者福祉、児童福祉などに充てられる。また、普通建設事業費は公共施設の建設などに充てられるとともに、不況時の景気対策に活用されることもある。図中のA〜Cに当てはまる項目の組合せとして正しいものを、次のうちから一つ選べ。",
