    "question": "国民が政治上の決定に携わるための制度は、国民が直接に政治上の決定に携わる直接民主制の理念に基づくものと、国民が代表者を通じて政治上の決定に携わる間接民主制の理念に基づくものとの二つに分類できる。次のA〜Cは、国民が政治上の決定に携わるような日本の制度である。これらのうち、直接民主制の理念に基づくものはどれか。最も適当なものを、次のうちから一つ選べ。\n\nA　公職選挙法に基づく議員選挙\nB　憲法改正のための国民投票\nC　条例の制定や改廃を求める住民の請求権",
