    "question": "裁判所は違憲立法審査権を積極的に行使し、必要な場合には違憲判断をためらうべきではないとする見解と、この権限を控えめに行使し、やむをえない場合のほかは違憲判断を避けるべきであるとする見解とが存在する。前者の根拠となる考え方として最も適当なものを、次のうちから一つ選べ。",
    "choices": [
      "人権保障は、とりわけ社会の少数派にとって重要であるから、多数派の考えに反しても確保されるべきである。",
      "法律制定の背景となる社会問題は複雑なものであり、国政調査権をもつ国会は、こうした問題を考慮するのにふさわしい立場にあるといえる。",
      "憲法は民主主義を原則としており、法律は、国民の代表である国会によって制定された民主主義的なものであるといえる。",
      "安全保障の基本的枠組みなど、国の根本を左右するような事項についての決定は、国民に対して政治的な責任を負う機関が行うべきである。"
    ],
    "answer": 0,
    "explanation": "違憲審査権を積極的に行使すべきだとする立場（司法積極主義）は、国会や内閣が多数派の意思で動くのに対し、選挙で選ばれない裁判所こそが少数者の人権を守れると考える。よって1が最も適当である。",
    "choiceNotes": [
      "正解。多数決では守られにくい少数者の人権を裁判所が確保すべきだという考え方で、違憲判断に積極的な立場の根拠となる。",
      "誤り。国政調査権をもつ国会の判断を尊重すべきだという、違憲判断に消極的な立場（司法消極主義）の根拠である。",
      "誤り。国民の代表が制定した法律を尊重すべきだという、司法消極主義の根拠である。",
      "誤り。政治的責任を負う機関の判断に委ねるべきだという統治行為論に通じる考え方で、司法消極主義の根拠である。"
    ],
