    "question": "デモに関連して、次の図は世界でデモが起きた国のいくつかを示したものである。図中の国A〜Cと説明ア〜ウとの組合せとして最も適当なものを、次のうちから一つ選べ。\n\nア　軍事政権の下、1988年に民主化を求めるデモが起き、多数の逮捕者が出た。その後、2010年に20年ぶりに行われた総選挙を経て選出された大統領により、これらの逮捕者の多くが釈放された。\nイ　2011年に、大統領退陣や経済改革などを求める大規模デモが起きた。その結果、30年にわたり政権を独占してきた大統領が辞任した。\nウ　2011年に、金融の中心地で、経済格差の是正や雇用の確保を求めるデモが始まり、全国各地に拡大していった。",
