    "explanation": "「法の支配」とは、権力者も法に従わなければならないという原理で、個人の権利を国家権力から守ることを目的とする。合法か違法かの判断を行政権をもつ法務大臣に委ねることは、権力者の判断次第で人の思想や行動が違法とされうることを意味し、法の支配ではなく「人の支配」に近づく。したがって2は有効な手法とは言えない。",
