    "noShuffle": true,
    "question": "自由は消極的自由と積極的自由の二つの概念に区別されるという考えがある。消極的自由とは、他人や政府によって干渉されない個人的な活動領域が確保されていること（他者による干渉の不在）である。積極的自由とは、個人ないし集団が自らの活動を自己以外の人物や権力者ではなく自己自身で支配すること（自己支配、自己実現）である。この考えに立ったとき、次の文章中の　ア　〜　エ　には消極的自由と積極的自由のどちらが入るか。その組合せとして最も適当なものを、次のうちから一つ選べ。\n\n　民主的な社会においては、人々は自分たちの社会のあり方について議論し決定する、あるいはその過程に参加することができるが、このことによって実現されるのは　ア　である。それに対して、非民主的な社会においても、権力者が人々の私生活に介入していなければ、論理的には　イ　が維持されているとみなされうる。\n　また、ある集団内で、人々の信じる価値は個人によって異なり、相互に対立することもあるが、その違いを尊重しあう場合には、　ウ　の方が重視されている。それに対して、人々が集団として内面の価値や目的を共有すべきであり、かつその目的が民主的に決定されるならば、集団の構成員すべてにその目的の追求を強制することも、　エ　の名の下に正当化されうる。",
