    "explanation": "社会保険の費用を「誰が」「なぜ」負担するのかを問う問題である。制度の理由づけまで押さえておきたい。\n【ア】雇用保険は、労使が保険料を出し合うだけでなく、失業等給付について国庫（政府）も負担している。失業は個々の企業や労働者の努力だけでは避けられず、景気や国の経済・雇用政策にも左右されるため、政府も責任を分担すべきだという考え方に基づく。よってbが入る。\n【イ】労災保険の保険料は、原則として全額を事業主が負担し、労働者の負担はない。労働災害は事業活動に伴って生じるものであり、その事業から利益を得る事業主が補償の費用を負うべきだという考え方（無過失責任・使用者責任の発想）による。よってdが入る。\nなお労災保険は、業務災害・通勤災害について、パートやアルバイトも含めすべての労働者が対象となる。",
