    "explanation": "付加価値とGDPの定義を確かめる基本問題である。\n付加価値額＝生産総額－中間投入物の額。\n・農家：中間投入物は0なので、付加価値は50万円。\n・製粉会社：小麦50万円分を投入して150万円で売ったので、ア＝50、ウ＝150－50＝100万円。\n・製パン会社：小麦粉150万円分を投入して400万円で売ったので、イ＝150、エ＝400－150＝250万円。\nGDP（国内総生産）は一定期間に国内で新たに生み出された付加価値の合計だから、\n　オ＝50＋100＋250＝400万円。\nこれは最終生産物であるパンの販売額400万円と一致する。同じ小麦の価値を何度も数える二重計算を避けるために中間投入物を差し引く、という考え方が要点である。600万円（50＋150＋400）は各社の売上を単純に足した二重計算、250万円は製パン会社の付加価値だけを見た誤りである。",
