    "noShuffle": true,
    "question": "GDP（国内総生産）の分配について、生徒Xと生徒Yが講義で学んだことを確認し合っている。次の会話文中の空欄　ア　には後の語句aかb、空欄　イ　には後の語句cかd、空欄　ウ　には後の記述eかfのいずれかが当てはまる。空欄　ア　～　ウ　に当てはまるものの組合せとして最も適当なものを、後のうちから一つ選べ。\n\nX：GDPは一国の経済活動の規模を表す指標だね。\nY：そうだね。GDPに海外からの純所得を加え、固定資本減耗を除き、そこからさらに間接税を差し引き、補助金を加えた額は　ア　と呼ばれるよ。　ア　は一国経済の中でどのように分配されるのかな。\nX：生産に貢献した者に分配されるんだよ。分配された総額が、どのように　イ　に充てられたかという点も興味深いね。\nY：確かにそうだね。生産面からみた総額と、分配面からみた総額と、　イ　面からみた総額とは、それぞれの大きさを比較するとどれが一番大きいのだろうか。\nX：もちろん、　ウ　よ。\n\n【ア に当てはまる語句】　a　GNI（国民総所得）　　b　NI（国民所得）\n【イ に当てはまる語句】　c　支出　　d　投資\n【ウ に当てはまる記述】　e　生産面からみた総額が一番大きい　　f　どの面からみた総額もすべて等しい",
