    "answer": 5,
    "explanation": "【ア】国民所得の諸指標は、次の順に計算する。\n　GDP＋海外からの純所得＝GNI（国民総所得）\n　GNI－固定資本減耗＝NNP（国民純生産）\n　NNP－間接税＋補助金＝NI（国民所得）\n会話文は「固定資本減耗を除き」「間接税を差し引き、補助金を加えた」まで進んでいるので、bのNI（国民所得）が入る。aのGNIは、GDPに海外からの純所得を加えた段階で止まってしまう。\n【イ・ウ】国民所得は、生産・分配・支出の三つの面からとらえられ、その総額はつねに等しくなる。これを三面等価の原則という。生み出された価値は必ず誰かに分配され、分配された所得は必ず消費・投資などの支出として使われる（使い残しは在庫投資として支出に数える）ため、事後的には一致する。よってイは「支出」、ウは「どの面からみた総額もすべて等しい」。「投資」は支出の一部にすぎないので、三面等価の1面の名前としては不適切である。",
