    "explanation": "GDPデフレーターは次の式で求める。\n　GDPデフレーター＝名目GDP÷実質GDP×100\n2020年について当てはめると、540÷360×100＝150。よってア＝d（150）。\n基準年（2010年）の値が100であるのに対して2020年は150なので、物価は50％上昇したことになる。よってイ＝e（上昇）。\n名目GDPは「その年の価格」で測った金額、実質GDPは「基準年の価格」で測り直した金額である。この例では実質GDPが400兆円から360兆円へ減っている（生産量は減っている）のに、名目GDPは400兆円から540兆円へ増えている。その差はすべて物価上昇によるものだ、という読み取りができる。\nなお66は360÷540×100と逆に割った値、135は540÷400×100と分母を取り違えた値である。",
