    "question": "同一の汚染物質を排出する企業Aと企業Bだけが存在するある地域を想定し、ある年の企業Aと企業Bの汚染水の年間排出量と汚染水に含まれる汚染物質の割合（汚染水の濃度）とを示す図の表を作成した。この地域で、汚染物質を減少させる規制を導入するとする。なお、企業Aと企業Bは次の仮定にしたがうものとする。この地域で1年間に排出される汚染水に含まれる汚染物質の総量を、いかなる場合においても規制導入以前より確実に減少させる規制の内容として正しいものを、後のうちから一つ選べ。\n\n【仮定】\n○規制導入以後は、企業Aも企業Bも、汚染水の年間排出量や汚染水の濃度を増減させる。\n○規制導入以後は、制限がかかったものについて企業Aも企業Bも、制限内の量や濃度で汚染水を排出する。\n○規制に対応するための費用は一切考慮しない。",
