    "answer": 2,
    "explanation": "汚染物質の量＝汚染水の排出量×濃度である。まず規制導入前の総量を出す。\n　企業A：100トン×1％＝1トン　　企業B：500トン×2％＝10トン　　合計11トン\n「いかなる場合においても確実に減少させる」とあるので、規制の下で企業がとりうる最悪の場合（＝上限いっぱいに排出した場合）を計算し、それが11トン未満になるかを確かめればよい。ここで重要なのは、量と濃度の片方しか制限しなければ、もう片方はいくらでも増やせてしまうという点である。\n3が正解。上限まで排出しても、A：120×1.5％＝1.8トン、B：600×1.5％＝9トンで合計10.8トン。11トンより確実に少ない。\n一見きびしそうな1や2が誤りになるのは、制限していない側を企業が自由に増やせるからである。環境規制を設計するときは、濃度だけでなく総量も同時に押さえる必要がある（総量規制の考え方）ことを示す問題である。",
