    "explanation": "【ア】人口ピラミッドの形から30年後を予測する。インドとインドネシアは若い世代ほど人口が多い「富士山型（ピラミッド型）」に近く、今の子どもたちがこれから生産年齢人口に入っていく。これに対して中国は、40代前後がふくらみ、0～4歳などの若い層が細くなった「つぼ型」に近い形をしている。一人っ子政策の影響もあって出生数が少ないため、2050年にはこの厚い層がまるごと65歳以上へ移り、生産年齢人口の割合は大きく落ち込む。よってアは中国。\n【イ】生産年齢人口（15～64歳）の割合が高まり、働き手が多く支えられる側が少ない状態を「人口ボーナス」、逆にその割合が低下し、高齢者などを支える負担が重くなる状態を「人口オーナス」という。オーナス（onus）は「重荷」の意味である。会話文は割合が低下する状態を指しているので、イは人口オーナス。\nよって⑤。日本は1990年代半ばに人口ボーナス期を終え、すでに人口オーナス期に入っている。",
