    "explanation": "【ア】金融資産を選ぶときの基準は、収益性（どれだけもうかるか）・安全性（元本が減らないか）・流動性（すぐ現金にできるか）の三つである。この三つは同時には満たせず、収益性が高いものは安全性や流動性が低くなるのが普通である。株式は値上がり益や配当が期待できる一方、値下がりで元本を失う危険があり、売買にも手間がかかる。よってアは「低い」。\n【イ】「資産が減る可能性を最も低くしたい」という考え方に合うのは、元本が保証される現金・預金の比率が最も高い構成である。資料では現金・預金の割合が日本54.3％、ユーロエリア34.3％、アメリカ13.3％なので、日本が当てはまる。\nよって①。日本の家計は現金・預金に偏り、アメリカは株式等（37.8％）や投資信託の比率が高いという対比は頻出である。",
