    "explanation": "図は、①経済不況以前 → ②不況で貸出債権の一部が不良債権になる → ③処理して資産から消し、その分だけ資本金が減る、という流れを表している。\n1が正解。自己資本比率＝自己資本（ここでは資本金）÷総資産である。不良債権処理で資本金が減れば、この比率は低下する。銀行は国際的な自己資本比率規制（BIS規制）を満たすため、比率を回復させなければならない。資本金（分子）をすぐに増やせないときは、貸出（分母）を減らして比率を上げようとする。これが新規貸出の抑制、すなわち貸し渋りにつながる。1990年代後半に公的資金を投入して銀行の資本金を増やしたのは、この悪循環を断ち切るためであった。\n「分子が減ったとき、分母を減らして比率を保とうとする」という力学が、貸し渋りの正体だという点をつかんでおきたい。",
