    "question": "経済のグローバル化によって人々の雇用や生活が受ける影響について、日本と発展途上国・新興国の関係を図のように整理した。図中の空欄　ア　には後のaかb、空欄　イ　には後のcかdのいずれかの記述が入る。その組合せとして最も適当なものを、後のうちから一つ選べ。\n\na　外資導入による輸出指向（志向）型での工業化の進展\nb　自国資本による輸入代替工業化の進展\nc　日本と発展途上国・新興国間の工業製品の貿易における日本の最終製品輸出比率の上昇と中間財輸入比率の上昇\nd　日本と発展途上国・新興国間の工業製品の貿易における日本の最終製品輸入比率の上昇と中間財輸出比率の上昇",
