    "explanation": "4が正解。日本のODA支出額（純額）は1991年から2000年まで、ほぼ連続して世界第一位を記録した。その後は財政事情などから減少し、順位も下がっている。\nODAの基本的な枠組みを整理しておきたい。ODAは、相手国に直接行う二国間援助（無償資金協力・技術協力・有償資金協力＝円借款）と、国際機関へ拠出する多国間援助に分かれる。日本は両方を実施しており、二国間援助の中でも円借款（返済義務のある貸付け）の比率が高いことが特徴とされてきた。\nまた、国連は先進国のODAについて対GNI比0.7％という目標を掲げているが、日本は長らく0.2～0.3％程度にとどまり、この目標を達成したことはない。",
