    "explanation": "【ア】マイクロファイナンスは、担保となる財産をもたない貧困層に対して、無担保で少額の資金を貸し出す金融サービスである。担保を求めてしまうと、そもそも担保を出せない貧しい人々が借りられず、制度の意味がなくなる。よってア＝無担保。担保の代わりに数人のグループを作らせて互いに返済を支え合わせるなど、返済率を高める工夫がなされている。\n【イ】バングラデシュで設立され、2006年にノーベル平和賞を受賞したのはグラミン銀行である。経済学者ムハマド・ユヌスが1983年に創設し、とくに女性への少額融資を通じて自立を支えた点が評価され、ユヌス氏とともに受賞した。\nアジアインフラ投資銀行（AIIB）は、中国が主導して2015年に設立された国際開発金融機関で、アジア地域の道路・鉄道・発電所などの大規模インフラ整備に資金を出す機関である。貧困層への少額融資とは目的も規模もまったく異なる。",
