    "question": "どのような財をどの程度輸出しているかを調べることで、その国の経済構造の特徴を知ることができる。2018年のデータとそれまでの各国の経済の動きをもとに、日本、中国、ナイジェリア、ロシアの貿易輸出品の主要3品目（主要品目の輸出額の輸出総額に占める割合）を示す次の表ア～エと、これらの国の経済的特徴をまとめた後の資料を作成した。資料を踏まえて表アに該当する国として正しいものを、次のうちから一つ選べ。\n\n【表】（いずれも2018年）\n表ア　原油28.6％／石油製品17.3％／鉄鋼5.4％\n表イ　機械類35.4％／自動車20.6％／精密機械5.8％\n表ウ　原油82.3％／液化天然ガス9.9％／船舶2.4％\n表エ　機械類43.8％／衣類6.3％／繊維と織物4.8％\n（注）商品分類は、標準国際貿易商品分類（SITC）の商品コードによる。機械類は、一般機械と電気機械である。\n\n【資料】\n　日本は、高度成長期以来、加工貿易型で経済発展してきた。中国は、経済特区を設けるなどして工業化を進め「世界の工場」といわれるほど発展し、アメリカに次ぐ経済規模の国になった。ロシアは、天然資源が多く、エネルギー価格の高騰を戦略的に活用し、2000年代に入ると鉱工業生産を伸ばした。ナイジェリアは、アフリカの中では経済規模が大きく人口も多いが、ODA（政府開発援助）を受け入れている発展途上国であり、モノカルチャー経済の特徴を示している。",
