    "explanation": "図では、需要曲線と供給曲線が交わる均衡価格がP₀、そのときの均衡数量がQ₀である。政府が価格を均衡価格より低いP₁に固定すると、価格P₁のもとで、買いたい量（需要量）はQ₂、売りたい量（供給量）はQ₁となり、Q₁＜Q₂となる。\n実際に取引が成立するのは、需要量と供給量の少ない方までである。売り手が用意する量を超えて買うことはできないので、取引数量は供給量のQ₁になる。\nまた、需要量Q₂が供給量Q₁を上回っているので、この市場ではQ₂−Q₁の超過需要（品不足）が発生している。価格の上限規制では品不足と行列・闇取引が生じやすい、という典型例である。",
