    "stem": "Ｘ：人口に関する本を読んでいたらイノベーションの話が出てきたよ。イノベーションが経済成長の源泉になっているんだね。そして経済成長の指標には実質GDP（国内総生産）が使われることが多いけど、仮に人口が減少し実質GDPが伸び悩む状況の下でも、　ア　考えると、イノベーションによる生産性の上昇があれば生活水準を高めることは可能だとわかると書いてあったよ。イノベーションを担うのは主に企業だから、企業の活動にはなるべく制約をかけず、新しい発想をもった企業が参入できることが必要なのではないかな。\nＹ：でも、自由な経済活動は必ずしもよいことばかりではないと思うよ。アイデアやデザインなどの知的財産権の保護を　イ　すぎると、せっかくのアイデアなどを勝手に使われてしまうね。逆に保護を　ウ　すぎると、アイデアなどを新しい研究開発に利用できなくなったり、高額の使用料を求められることになったりするね。結局どちらもイノベーションを妨げる要因となるかもしれないよ。\nＸ：なるほど、健全な経済活動の維持発展には企業の行動をバランスよく規制することも重要なんだね。\nＹ：そのための司法や行政の役割も調べてみよう。",
