    "explanation": "ア：人口が減っているときは、GDPの総額が伸び悩んでも、それを人数で割った一人当たりGDPは増えうる。生活水準を測るには一人当たりで考えるのが適切である。固定資本減耗を控除するのはGDPからNDP（国内純生産）を求める操作で、人口減少の話とは関係がない。イ：保護が弱すぎればアイデアを勝手に使われてしまう。ウ：保護が強すぎればアイデアを新たな研究開発に使えなくなったり高額の使用料を求められたりする。よって「一人当たりで・弱め・強め」。",
