    "stem": "企業間の競争が激化すると、コスト削減などのために企業が製品の安全性を軽視し、消費者に被害が生じることがある。こうした問題に対処するために消費者を保護する法制度が整備されており、そうした法制度の一例として製造物責任法がある。日本の製造物責任法では、消費者が企業に賠償を求めるためには、　ア　。\n消費者に生じる被害への対策は、一般に、問題の発生を防ぐために企業の参入の前や製品の販売の前に規制を行う事前規制と、問題を発生させた企業を取り締まったり被害者の救済を図ったりする事後規制の二つに分類される。日本の製造物責任法に基づき企業に賠償責任を負わせることは、その二つのうち、　イ　に分類される。\n\nアに当てはまる記述\nａ　製品の欠陥の証明と企業の過失の証明とが両方とも必要である\nｂ　製品の欠陥の証明は必要であるが、企業の過失の証明は不要である\nｃ　製品の欠陥の証明は不要であるが、企業の過失の証明は必要である\nｄ　製品の欠陥の証明と企業の過失の証明とが両方とも不要である\n\nイに当てはまる語句\nｅ　事前規制\nｆ　事後規制",
