    "stemTitle": "リード文　格差と格差是正",
    "stem": "経済の発展に伴って、人類はかつてないほどの物質的繁栄を達成した。しかし、繁栄の果実を享受できるものと、できないものとの格差が顕著になり、格差是正が課題となっている。\n先進国と発展途上国との国家間格差をめぐっては、発展途上国を支援する開発援助の方法や、格差を考慮した国際貿易の仕組みが議論されてきた。また、国家間格差は環境問題とも関係している。先進国は産業革命以降、大量のエネルギーを消費し、汚染物質を排出しながら経済発展を遂げてきた。それにもかかわらず、すべての国に一律の環境規制を課すことは、発展途上国にとって大きな負担となり、国家間格差を残存させるおそれがある。近年では、気候変動をめぐる国際交渉においても、発展途上国への配慮がなされている。\n一国内でも、都市部と農村部との関係など、地域間格差がしばしば問題視される。たとえば日本では、中央政府と地方政府の間で補助金などを用いて地域間格差の是正に取り組んでいる。ただし、格差是正の方法は多様であり、効果的な政策のあり方が絶えず議論されている。\n個人間格差をめぐっては、19世紀以降、各国政府は社会保障制度の整備を通じて所得再分配を行い、より公平性の高い社会を実現しようとしてきた。しかし、公平性の追求が、経済効率性を損なうとの意見もある。このような、公平性と効率性の　ア　をいかに解決するかが問われている。関連して、近年では、教育機会の均等化をめぐる議論や、一律一定額を全国民に給付する　イ　が注目されている。",
    "question": "本文中の空欄ア・イに当てはまる語句の組合せとして最も適当なものを、次のうちから一つ選べ。",
