    "explanation": "ア　一方を追求すればもう一方が犠牲になる関係をトレード・オフという。ここでは、公平性を高めようとすると効率性が損なわれるという関係を指している。プライマリー・バランス（基礎的財政収支）は、国債の発行と元利払いを除いた歳入と歳出の差であり、公平性と効率性の関係を表す語ではない。\nイ　所得や就労の有無にかかわらず、すべての人に一律一定額を給付する構想をベーシック・インカムという。ユニバーサル・デザインは、年齢や障害の有無にかかわらず誰もが使いやすいように製品や環境を設計する考え方で、給付の仕組みではない。\nよって1が正しい。",
