    "answer": 1,
    "explanation": "ア　資本家階級と労働者階級の分化、搾取という語から、『資本論』を著して科学的社会主義を唱えたマルクスである。マルサスは『人口論』で人口が食料生産を上回って増えることを論じた古典派の経済学者で、搾取のない社会の実現を主張した人ではない。\nイ　政府の裁量的な政策を批判し、通貨供給量を一定の率で増やすことなどルールに基づく政策を主張したのは、マネタリズムを唱えたフリードマンである。ガルブレイスは『ゆたかな社会』などで大衆消費社会を分析した経済学者で、むしろ社会的な支出の必要を説いた。\nよって2が正しい。",
