    "explanation": "管理通貨制度は、通貨の発行量を金の保有量に縛られず、中央銀行や政府が経済の状況に応じて調節する制度である。これに対し金本位制では、中央銀行が保有する金の量が通貨の発行量を制限した。よって3が正しい。\n世界恐慌を経て各国は金本位制を離れ、現在はどの国も管理通貨制度をとっている。景気に応じた通貨供給ができる反面、発行が行き過ぎればインフレーションを招く危険がある。",
