    "question": "上の表は、日本とギリシャとにおける政府債務残高の対GDP（国内総生産）比と経常収支の対GDP比とを示したものである。この表から読みとれることを参考にしつつ、次の文章中の空欄ア・イに当てはまる語句の組合せとして正しいものを、次のうちから一つ選べ。\n\n日本とギリシャとの政府債務残高の対GDP比を比べると、財政破綻が懸念されるギリシャの方が　ア　。このことは、政府債務残高のGDPに対する比率が一定の水準に達すれば財政危機が必ず生じるとは限らないことを示している。他方、経常収支をみると、ギリシャについては、財政危機が生じた2010年まで常に赤字であった。ギリシャは、この赤字分を対外債務の　イ　によって埋め合わせていたことになる。",
