    "explanation": "1が正しい。企業が生み出した利潤のうち、税や配当として社外に出ず企業内部に蓄えられた分を内部留保という。内部留保は借入れによらない自己資金として設備投資などにあてることができ、企業規模の拡大を支える原資になる。\n利潤をめぐっては、①利潤＝収入−費用という定義、②国民経済計算での区分（賃金は雇用者報酬、企業の利潤は営業余剰）、③株主が払い込むのが出資金、株主が受け取るのが配当、という三点を区別して押さえておきたい。",
