    "question": "経済活動を規制したり経済主体を保護したりすることを目的としている法律A〜Cと、それらの法律が必要とされる理由ア〜ウとの組合せとして最も適当なものを、次のうちから一つ選べ。\n\nA　独占禁止法\nB　大気汚染防止法\nC　消費者契約法\n\nア　売り手と買い手との間に、情報や交渉力の格差があるため\nイ　経済活動が、市場を通さずに他の経済主体に悪影響を及ぼす場合があるため\nウ　市場取引に任せると、公正かつ自由な競争が行われない場合があるため",
