    "stemTitle": "図　スポーツ用品の市場と均衡の移動（矢印A〜D）",
    "stem": "図には、右上がりの供給曲線と右下がりの需要曲線が実線で描かれ、その交点が当初の均衡点である。さらに、需要曲線・供給曲線をそれぞれ平行移動させた破線が描かれ、当初の均衡点のまわりに四つの新しい均衡点がある。矢印A〜Dは、当初の均衡点からそれぞれの新しい均衡点への移動を表す。\nA　左上向きの矢印。価格が上がり、数量が減る。\nB　左下向きの矢印。価格が下がり、数量が減る。\nC　右下向きの矢印。価格が下がり、数量が増える。\nD　右上向きの矢印。価格が上がり、数量が増える。",
    "question": "企業活動のあり方の変化は、市場に対して影響をもたらす場合がある。上の図には、スポーツ用品の需要曲線と供給曲線が実線で描かれており、図中の矢印A〜Dは均衡の移動を表している。スポーツ用品の生産者は、当初、賃金の安い児童を多く雇用していたが、その後、国際NGO（非政府組織）の働きかけなどにより、生産者には国際的な労働基準を遵守することが求められるようになったとしよう。そのため、生産者は児童を雇用せず、より高い賃金を支払うようになったとする。他の条件を一定として、当初の均衡から、生産者が高い賃金を支払うようになった後の均衡への移動を表すものとして正しいものを、次のうちから一つ選べ。",
    "choices": [
      "A",
      "B",
      "C",
      "D"
    ],
    "answer": 0,
    "explanation": "児童を雇わずより高い賃金を支払うようになることは、生産コストの上昇である。生産コストが上がると、同じ価格で供給できる量が減るので、供給曲線が左（上）へ移動する。他の条件は一定なので需要曲線は動かない。その結果、均衡価格は上がり、均衡数量は減る。これは価格が上がり数量が減るAの移動であり、1が正解である。",
    "choiceNotes": [
      "正解。供給曲線が左（上）へ移動し、価格が上がって数量が減る移動である。",
      "誤り。価格も数量も下がる移動で、需要曲線が左へ移動した場合に当たる。賃金の上昇は需要曲線を動かさない。",
      "誤り。価格が下がり数量が増える移動で、供給曲線が右へ移動した（生産コストが下がった）場合に当たる。",
      "誤り。価格も数量も上がる移動で、需要曲線が右へ移動した（この財の人気が高まった、所得が増えたなど）場合に当たる。"
    ],
