    "question": "欠陥商品の被害者救済は消費者保護政策の一環であり、この政策展開の出発点となったのは、アメリカのケネディ大統領が提唱した「消費者の四つの権利」である。この権利のうち一つは「知らされる権利」であり、次のA〜Cは、その他の三つの権利の内容を説明したものである。下のア〜ウは、これら三つの権利を保護、または侵害する例である。A〜Cとア〜ウとの組合せとして最も適当なものを、次のうちから一つ選べ。\n\nA　生命や健康にとって危険な製品の販売から保護される、という「安全を求める権利」\nB　政府の政策立案において、消費者の利益が十分に考慮され、行政手続においては、公正で迅速な行政上の対応が保障される、という「意見を聞いてもらう権利」\nC　できる限り多様な製品やサービスを、競争価格で入手できるよう保障される、という「選択できる権利」\n\nア　欠陥車に関する自動車のリコール制度\nイ　食品健康影響評価に関するパブリック・コメント\nウ　同一産業内の企業によるカルテル",
